impl<W: Worker> Transport<W::Role> for WorkerTransport<W> {
    type Error = W::Error;

    fn send(
        &mut self,
        item: TxJsonRpcMessage<W::Role>,
    ) -> impl Future<Output = Result<(), Self::Error>> + Send + 'static {
        let tx = self.send_service.clone();
        let (responder, receiver) = tokio::sync::oneshot::channel();
        let request = WorkerSendRequest {
            message: item,
            responder,
        };
        async move {
            tx.send(request).await.map_err(|_| W::err_closed())?;
            receiver.await.map_err(|_| W::err_closed())??;
            Ok(())
        }
    }
    async fn receive(&mut self) -> Option<RxJsonRpcMessage<W::Role>> {
        self.rx.recv().await
    }
    async fn close(&mut self) -> Result<(), Self::Error> {
        if let Some(handle) = self.join_handle.take() {
            self.ct.cancel();
            let _quit_reason = handle.await.map_err(W::err_join)?;
            Ok(())
        } else {
            Ok(())
        }
    }

// Extract the negotiated protocol version from the init response
// and build a custom headers map that includes MCP-Protocol-Version
// for all subsequent HTTP requests (per MCP 2025-06-18 spec).
let mut protocol_headers = {
    let mut headers = config.custom_headers.clone();
    if let ServerJsonRpcMessage::Response(response) = &message {
        if let ServerResult::InitializeResult(init_result) = &response.result {
            if let Ok(hv) = HeaderValue::from_str(init_result.protocol_version.as_str()) {
                // HeaderName::from_static requires lowercase
                headers.insert(HeaderName::from_static("mcp-protocol-version"), hv);
            }
        }
    }
    headers
};

// Store session info for cleanup when run() exits (not spawned, so cleanup completes before close() returns)
let mut session_cleanup_info = session_id.as_ref().map(|sid| SessionCleanupInfo {
    client: self.client.clone(),
    uri: config.uri.clone(),
    session_id: sid.clone(),
    auth_header: config.auth_header.clone(),
    protocol_headers: protocol_headers.clone(),
});

context.send_to_handler(message).await?;
let initialized_notification = context.recv_from_handler().await?;
// expect a initialized response
self.client
    .post_message(
        config.uri.clone(),
        initialized_notification.message,
        session_id.clone(),
        config.auth_header.clone(),
        protocol_headers.clone(),
    )
    .await
    .map_err(WorkerQuitReason::fatal_context(
        "send initialized notification",
    ))?
    .expect_accepted_or_json::<C::Error>()

}
// Main event loop - capture exit reason so we can do cleanup before returning
let loop_result: Result<(), WorkerQuitReason<Self::Error>> = 'main_loop: loop {
    let event = tokio::select! {
        _ = transport_task_ct.cancelled() => {
            tracing::debug!("cancelled");
            break 'main_loop Err(WorkerQuitReason::Cancelled);
        }
        message = context.recv_from_handler() => {
            match message {
                Ok(msg) => Event::ClientMessage(msg),
                Err(e) => break 'main_loop Err(e),
            }
        },
        message = sse_worker_rx.recv() => {
            let Some(message) = message else {
                tracing::trace!("transport dropped, exiting");
                break 'main_loop Err(WorkerQuitReason::HandlerTerminated);
            };
            Event::ServerMessage(message)
        },
        terminated_stream = streams.join_next(), if !streams.is_empty() => {
            match terminated_stream {
                Some(result) => {
                    Event::StreamResult(result.map_err(StreamableHttpError::TokioJoinError).and_then(std::convert::identity))
                }
                None => {
                    continue
                }
            }
        }
    };
    match event {
        Event::ClientMessage(send_request) => {
            let WorkerSendRequest { message, responder } = send_request;
            // Pass a clone to the first attempt so `message` is retained for a
            // potential re-init retry. `post_message` takes ownership and the
            // trait cannot be changed, so the clone is unavoidable.
            let response = self
                .client
                .post_message(
                    config.uri.clone(),
                    message.clone(),
                    session_id.clone(),
                    config.auth_header.clone(),
                    protocol_headers.clone(),
                )
                .await;
            let send_result = match response {
                Err(StreamableHttpError::SessionExpired) => {
                    if !config.reinit_on_expired_session {
                        Err(StreamableHttpError::SessionExpired)
                    } else {
                        // The server discarded the session (HTTP 404). Perform a

                    Ok(())
                }
            };
            let _ = responder.send(send_result);
        }
        Event::ServerMessage(json_rpc_message) => {
            // send the message to the handler
            if let Err(e) = context.send_to_handler(json_rpc_message).await {
                break 'main_loop Err(e);
            }
        }
        Event::StreamResult(result) => {
            if result.is_err() {
                tracing::warn!(
                    "sse client event stream terminated with error: {:?}",
                    result
                );
            }
        }
    }
};

// Cleanup session before returning (ensures close() waits for session deletion)
// Use a timeout to prevent indefinite hangs if the server is unresponsive
if let Some(cleanup) = session_cleanup_info {
    const SESSION_CLEANUP_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(5);
    let cleanup_session_id = cleanup.session_id.clone();
    match tokio::time::timeout(
        SESSION_CLEANUP_TIMEOUT,
        cleanup.client.delete_session(
            cleanup.uri,
            cleanup.session_id,
            cleanup.auth_header,
            cleanup.protocol_headers,
        ),
    )

async fn shutdown(&self) -> AppResult<()> {
    self.capacity.close();
    self.close_endpoint_capacity();
    self.shutdown.cancel();
    let mut workers = self.workers.lock().await;
    let mut failed_worker = false;
    while let Some(result) = workers.join_next().await {
        failed_worker |= result.is_err();
    }
    if failed_worker {
        return Err(failed("MCP worker shutdown failed"));
    }
    Ok(())
}

async fn call(&self, name: &McpToolName, arguments: Value) -> AppResult<McpCallResult> {
    self.remaining
        .store(MAX_MCP_DISCOVERY_BYTES, std::sync::atomic::Ordering::SeqCst);
    if arguments.to_string().len() > MAX_MCP_SCHEMA_BYTES {
        return Err(failed("MCP arguments exceed 64 KiB"));
    }
    let args = arguments
        .as_object()
        .cloned()
        .ok_or_else(|| failed("MCP arguments must be an object"))?;
    let request = rmcp::model::CallToolRequest::new(
        CallToolRequestParams::new(name.as_str().to_owned()).with_arguments(args),
    );
    let handle = self
        .client
        .send_cancellable_request(
            request.into(),
            rmcp::service::PeerRequestOptions::no_options(),
        )
        .await
        .map_err(|error| errors::service(error, "MCP effect indeterminate; do not retry"))?;
    *self
        .pending_call
        .lock()
        .map_err(|_| failed("MCP session unavailable"))? = Some(handle.id.clone());
    let response = tokio::time::timeout(Duration::from_secs(30), handle.await_response()).await;
    if response.is_ok() {
        self.pending_call
            .lock()
            .map_err(|_| failed("MCP session unavailable"))?
            .take();
    }
    let result = response
        .map_err(|_| failed("MCP effect indeterminate; do not retry"))?
        .map_err(|error| errors::service(error, "MCP effect indeterminate; do not retry"))?;
    let rmcp::model::ServerResult::CallToolResult(result) = result else {
        return Err(failed("MCP effect indeterminate; do not retry"));
    };
    self.parse_result(result)
}
async fn close(mut self: Box<Self>) -> AppResult<()> {
    self.cancel_pending().await;
    self.stop.cancel();
    let closed = self
        .client
        .close_with_timeout(Duration::from_secs(35))
        .await;
    if let Some(finished) = self.finished.take() {
        finished
            .await
            .map_err(|_| failed("MCP HTTP cleanup failed"))?;
    }
    self.cleanup
        .finish()
        .await
        .map_err(|_| failed("MCP session cleanup failed"))?;
    closed
        .map_err(|_| failed("MCP shutdown failed"))?
        .ok_or_else(|| failed("MCP shutdown timed out"))?;
    Ok(())
}

async fn cancel_pending(&self) {
    let pending = self.pending_call.lock().ok().and_then(|mut id| id.take());
    if let Some(request_id) = pending {
        let params = rmcp::model::CancelledNotificationParam {
            request_id,
            reason: Some("Local execution cancelled".into()),
        };
        let _ =
            tokio::time::timeout(Duration::from_secs(3), self.client.notify_cancelled(params))
                .await;
    }
}

pub(super) struct Cleanup {
    pub client: reqwest::Client,
    pub endpoint: String,
    pub token: Option<SecretString>,
    pub session: Arc<std::sync::Mutex<Option<SessionIdentity>>>,
}
pub(super) struct SessionIdentity {
    id: String,
    headers: HashMap<HeaderName, HeaderValue>,
}
impl Cleanup {
    pub async fn finish(&self) -> Result<(), Error> {
        let session = self
            .session
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .take();
        if let Some(SessionIdentity { id, headers }) = session {
            tokio::time::timeout(
                std::time::Duration::from_secs(5),
                delete(
                    &self.client,
                    &self.endpoint,
                    &id,
                    self.token.as_ref().map(|t| t.expose_secret().to_owned()),
                    headers,
                ),
            )
            .await
            .map_err(|_| failed())??;
        }
        Ok(())
    }
}
fn failed() -> Error {
    StreamableHttpError::Client(HttpFailure::Unavailable)
}
impl BoundedHttp {
    fn request(
        client: &reqwest::Client,
        method: Method,
        uri: &str,
        session: Option<&str>,
        token: Option<String>,
        headers: HashMap<HeaderName, HeaderValue>,
    ) -> Result<reqwest::RequestBuilder, Error> {
        let mut request = client
            .request(method, uri)
            .header("accept", "application/json, text/event-stream");
        if let Some(session) = session {
            request = request.header("mcp-session-id", session);
        }
        if let Some(token) = token {
            let mut value =
                HeaderValue::from_str(&format!("Bearer {token}")).map_err(|_| failed())?;
            value.set_sensitive(true);
            request = request.header("authorization", value);
        }
        // Only rmcp's negotiated protocol header is needed. No tenant-supplied headers exist.
        for (name, value) in headers {
            if name == "mcp-protocol-version" {
                request = request.header(name, value);
            }
        }
        Ok(request)
    }

